INDEX_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1" />\n<title>PSE Split Automation</title>\n<style>\n  :root { --bg:#f6f8f9; --panel:#fff; --line:#e2e7eb; --text:#1b2733; --muted:#68737d; --teal:#17494d; --lime:#78a300; --warn:#b26a00; --ok:#3f8c00; --chip:#eef1f3; }\n  * { box-sizing:border-box; }\n  body { margin:0; background:var(--bg); color:var(--text); font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; }\n  header { display:flex; align-items:center; gap:16px; flex-wrap:wrap; padding:16px 24px; background:var(--panel); border-bottom:1px solid var(--line); position:sticky; top:0; z-index:10; }\n  h1 { margin:0; font-size:20px; font-weight:700; } .sub { color:var(--muted); font-size:12px; }\n  .spacer { flex:1; }\n  button { border:0; border-radius:8px; padding:9px 15px; background:var(--teal); color:white; font:inherit; font-weight:650; cursor:pointer; }\n  button:hover { background:#23646a; } button:disabled { opacity:.5; cursor:wait; }\n  button.ghost { border:1px solid var(--line); background:white; color:var(--text); } button.ghost:hover { background:#f3f5f7; }\n  main { max-width:1500px; margin:0 auto; padding:24px; }\n  .cards { display:grid; grid-template-columns:repeat(3,minmax(150px,1fr)); gap:14px; margin-bottom:20px; }\n  .card { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:15px 18px; min-height:96px; }\n  .card .k { color:var(--muted); font-size:12px; text-transform:uppercase; letter-spacing:.45px; }\n  .category-card { display:block; text-align:left; color:var(--text); font-weight:400; cursor:pointer; width:100%; font:inherit; }\n  .category-card span { display:block; }\n  .category-card:hover { background:#edf5f3; border-color:#83a8a4; }\n  .category-card.selected { background:#eaf3f1; border:2px solid var(--teal); padding:14px 17px; }\n  .category-card .v { color:var(--teal); }\n  .category-context { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px; margin:0 0 15px; font-weight:650; }\n  .card .v { font-size:28px; font-weight:720; margin-top:5px; } .card.ok .v { color:var(--ok); } .card.warn .v { color:var(--warn); }\n  .toolbar { display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:12px; }\n  input[type=search],select { min-height:40px; padding:8px 12px; border:1px solid var(--line); border-radius:8px; background:#f3f5f7; color:var(--text); font:inherit; }\n  input[type=search] { flex:1; min-width:250px; } select { min-width:150px; cursor:pointer; }\n  .multi-filter { position:relative; }\n  .filter-trigger { display:flex; align-items:center; justify-content:space-between; gap:16px; min-width:170px; min-height:40px; padding:8px 12px; border:1px solid var(--line); border-radius:8px; background:#f3f5f7; color:var(--text); font:inherit; font-weight:500; text-align:left; }\n  .filter-trigger::after { content:"▾"; color:var(--muted); font-size:12px; }\n  .filter-menu { position:absolute; z-index:20; top:calc(100% + 5px); left:0; width:240px; max-height:300px; overflow:auto; border:1px solid var(--line); border-radius:9px; background:white; box-shadow:0 8px 24px rgba(27,39,51,.14); }\n  .filter-menu.hidden { display:none!important; }\n  .filter-option { display:flex; align-items:center; gap:9px; padding:8px 12px; cursor:pointer; }\n  .filter-option:hover { background:#f3f5f7; }\n  .filter-option input { accent-color:var(--teal); }\n  .filter-actions { position:sticky; bottom:0; display:flex; justify-content:space-between; padding:7px 10px; border-top:1px solid var(--line); background:#fff; }\n  .filter-actions button { padding:4px 6px; background:transparent; color:var(--teal); font-size:12px; }\n  .filter-actions button:hover { background:#f3f5f7; }\n  h2 { margin:16px 0 12px; font-size:17px; font-weight:680; }\n  .opp-title { font-size:15px; font-weight:680; }\n  .account-name { font-weight:630; } .pse-name { font-weight:650; color:var(--teal); }\n  .pill { display:inline-block; border-radius:999px; padding:2px 9px; background:#e9f3e9; color:var(--ok); font-size:11px; font-weight:700; white-space:nowrap; }\n  .pill.warn { background:#fff0d4; color:var(--warn); }\n  .bulk-bar { display:flex; align-items:center; gap:14px; flex-wrap:wrap; margin-bottom:14px; padding:13px 17px; background:var(--panel); border:1px solid var(--line); border-radius:12px; box-shadow:inset 3px 0 0 var(--warn); }\n  .bulk-info { font-weight:680; }\n  .action-list { display:grid; gap:14px; }\n  .action-card { overflow:hidden; background:var(--panel); border:1px solid var(--line); border-radius:12px; box-shadow:inset 3px 0 0 var(--warn); }\n  .action-card.is-tagged { box-shadow:inset 3px 0 0 var(--ok); }\n  .action-head { display:flex; align-items:flex-start; gap:16px; padding:15px 18px; }\n  .head-main { flex:1; min-width:0; } .action-head .btn-update { flex-shrink:0; white-space:nowrap; }\n  a.btn-update { display:inline-flex; align-items:center; border-radius:8px; padding:9px 15px; background:var(--teal); color:#fff; font-weight:650; text-decoration:none; }\n  a.btn-update:hover { background:#23646a; }\n  .details-line { margin-top:4px; color:var(--muted); font-size:12px; overflow-wrap:anywhere; }\n  .pse-tag { display:inline-flex; align-items:center; gap:8px; margin-top:9px; padding:4px 10px; border-radius:7px; background:#eaf2f1; color:var(--teal); }\n  .action-steps { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:20px; padding:14px 18px 16px; border-top:1px solid var(--line); }\n  .step { min-width:0; }\n  .step-title { font-size:14px; font-weight:700; }\n  .step-path { margin-top:3px; color:var(--muted); font-size:12px; }\n  .step-values { width:min(100%,420px); margin-top:4px; border-collapse:collapse; overflow:hidden; border-radius:8px; background:#f1f3f5; }\n  .step-values td { padding:7px 14px; border-bottom:1px solid var(--line); }\n  .step-values tr:last-child td { border-bottom:0; }\n  .step-values td:first-child { color:var(--muted); font-weight:650; white-space:nowrap; }\n  .step-values td:last-child { font-weight:650; }\n  .also { margin-top:7px; color:var(--muted); font-size:12px; }\n  .msg { margin-top:5px; font-weight:650; } .msg.ok { color:var(--ok); } .msg.err { color:#b42318; }\n  .pagination { display:flex; justify-content:flex-end; align-items:center; gap:9px; padding:11px 2px; color:var(--muted); font-size:12px; }\n  .pagination button { padding:6px 11px; font-size:12px; }\n  .empty,.status { padding:40px 20px; text-align:center; color:var(--muted); } .status.err { color:#b42318; }\n  .hidden { display:none!important; } #refreshMsg.err { color:#b42318; } #refreshMsg.ok { color:var(--ok); }\n  a { color:var(--teal); text-decoration:none; } a:hover { text-decoration:underline; }\n  @media(max-width:900px) { .cards { grid-template-columns:repeat(2,minmax(145px,1fr)); } .action-head { flex-direction:column; } .action-steps { grid-template-columns:1fr; gap:14px; } }\n  @media(max-width:600px) { main { padding:16px; } header { padding:14px 16px; } .cards { gap:8px; } input[type=search] { min-width:100%; } }\n\n  dialog.process-page { position:fixed; inset:0; width:100vw; max-width:none; height:100dvh; max-height:none; margin:0; padding:0; border:0; background:var(--bg); color:var(--text); }\n  dialog.process-page::backdrop { background:rgba(0,0,0,.3); }\n  .process-bar { position:sticky; top:0; z-index:2; display:flex; align-items:center; gap:20px; padding:18px max(24px,calc((100vw - 1100px)/2)); background:white; border-bottom:1px solid var(--line); }\n  .process-bar .process-brand { margin:0; font-size:22px; font-weight:700; } .process-bar button { margin-left:auto; white-space:nowrap; }\n  .process-content { max-width:1100px; margin:auto; padding:32px 24px 50px; }\n  .process-intro { max-width:760px; } .process-intro h2 { font-size:32px; font-weight:750; line-height:1.2; margin:0 0 8px; }\n  .process-intro p { margin:0; font-size:14px; font-weight:400; color:var(--muted); }\n  .process-scope { margin:20px 0; color:var(--teal); }\n  .flow-step { position:relative; background:white; border:1px solid var(--line); border-radius:14px; padding:22px; }\n  .flow-step h3 { margin:0 0 10px; display:flex; align-items:center; gap:12px; font-size:17px; }\n  .step-number { display:inline-grid; place-items:center; width:32px; height:32px; border-radius:50%; background:var(--teal); color:white; flex-shrink:0; }\n  .flow-arrow { text-align:center; color:var(--teal); font-size:24px; height:38px; }\n  .branches { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-top:14px; }\n  .branch { background:#f4f7f7; border-radius:9px; padding:15px; } .branch strong { display:block; color:var(--teal); margin-bottom:5px; }\n  .branch p { margin:0; } .process-note { margin:12px 0 0; padding:12px 15px; background:#fff4dd; border-radius:8px; }\n  .flow-step dl { display:grid; grid-template-columns:max-content 1fr; gap:6px 16px; margin:12px 0 0; } .flow-step dt { color:var(--muted); } .flow-step dd { margin:0; font-weight:600; }\n  .process-help { margin-top:28px; background:white; padding:22px; border-radius:14px; border:1px solid var(--line); }\n  .process-help h3 { margin:0 0 12px; } .process-help p { margin:10px 0; }\n  .process-help h4 { margin:22px 0 8px; font-size:15px; color:var(--teal); }\n  .process-help ol { padding-left:24px; } .process-help li { margin:10px 0; padding-left:4px; }\n  .help-filters { display:grid; grid-template-columns:minmax(130px,180px) 1fr; gap:12px 18px; margin:16px 0; }\n  .help-filters dt { font-weight:650; } .help-filters dd { margin:0; }\n  @media(max-width:600px) { .help-filters { grid-template-columns:1fr; gap:4px; } .help-filters dd { margin-bottom:12px; } }\n  .text-link { padding:0; background:transparent; color:var(--teal); font:inherit; font-weight:650; text-decoration:underline; text-underline-offset:3px; }\n  .text-link:hover { background:transparent; color:#23646a; }\n  .setup-prompt { display:block; width:100%; min-height:420px; padding:16px; border:1px solid var(--line); border-radius:8px; background:#f3f5f7; color:var(--text); font:13px/1.6 ui-monospace,monospace; resize:vertical; }\n  .setup-actions { display:flex; flex-wrap:wrap; gap:12px; align-items:center; margin:12px 0; }\n  button:focus-visible, a:focus-visible { outline:3px solid #6a9fa3; outline-offset:3px; }\n  @media(max-width:650px) { .branches { grid-template-columns:1fr; } .process-intro h2 { font-size:25px; } .process-bar { padding:14px 16px; } .flow-step { padding:16px; } }\n</style>\n</head>\n<body>\n<header>\n  <div><h1>PSE Split Automation</h1></div>\n  <div class="spacer"></div>\n  <span id="refreshMsg" class="sub" aria-live="polite"></span><span id="who" class="sub"></span>\n  <button class="ghost" id="processFlowBtn">Process Flow</button>\n  <button class="ghost hidden" id="uploadDataBtn">Upload the data</button><button class="ghost hidden" id="refreshBtn">Refresh</button><button id="csvBtn">Export CSV</button>\n</header>\n<main>\n  <div id="status" class="status">Loading dashboard data…</div>\n  <section id="dashboard" class="hidden">\n    <div class="cards" role="group" aria-label="Filter Opportunities by PSE assignment">\n      <button type="button" class="card category-card" data-pse-category="tagged" aria-pressed="false" aria-controls="panelUpdate"><span class="k">Opportunities with tagged PSE</span><span class="v" id="cWithPse">—</span><span class="sub">Partner + tagged PSE · missing Team or Split</span></button>\n      <button type="button" class="card category-card" data-pse-category="untagged" aria-pressed="false" aria-controls="panelUpdate"><span class="k">Partner but no tagged PSE</span><span class="v" id="cWithoutPse">—</span><span class="sub">PSE blank · Partner Owner missing from Team or Split</span></button>\n      <button type="button" class="card category-card selected" data-pse-category="all" aria-pressed="true" aria-controls="panelUpdate"><span class="k">All Opportunities to update</span><span class="v" id="cNeedsUpdate">—</span><span class="sub">Both categories · missing Team or Split</span></button>\n    </div>\n    <div class="category-context"><span id="categoryLabel" aria-live="polite">Showing all Opportunities to update</span><span class="sub">Card counts follow your search and filters. Select a box to filter the list.</span></div>\n    <div class="toolbar">\n      <input type="search" id="search" placeholder="Search Opportunity name, Account name, or Opp ID…" />\n      <div class="multi-filter" id="quarterFilter" data-filter-title="Fiscal Quarter–Year" data-filter-key="fiscalQuarter" data-filter-label="fiscal quarters" title="Based on Close Date. Zendesk fiscal year: February–January.">\n        <button type="button" class="filter-trigger" id="quarterFilterButton" aria-haspopup="true" aria-expanded="false" aria-controls="quarterFilterMenu">Fiscal Quarter–Year</button>\n        <div class="filter-menu hidden" id="quarterFilterMenu" role="group" aria-label="Fiscal Quarter-Year options"></div>\n      </div>\n      <div class="multi-filter" id="typeFilter" data-filter-title="Opportunity Type" data-filter-key="type" data-filter-label="types">\n        <button type="button" class="filter-trigger" id="typeFilterButton" aria-haspopup="true" aria-expanded="false" aria-controls="typeFilterMenu">Opportunity Type</button>\n        <div class="filter-menu hidden" id="typeFilterMenu" role="group" aria-label="Opportunity Type options"></div>\n      </div>\n      <div class="multi-filter" id="segmentFilter" data-filter-title="Market Segment" data-filter-key="segment" data-filter-label="segments">\n        <button type="button" class="filter-trigger" id="segmentFilterButton" aria-haspopup="true" aria-expanded="false" aria-controls="segmentFilterMenu">Market Segment</button>\n        <div class="filter-menu hidden" id="segmentFilterMenu" role="group" aria-label="Market Segment options"></div>\n      </div>\n      <div class="multi-filter" id="regionFilter" data-filter-title="Region" data-filter-key="region" data-filter-label="regions">\n        <button type="button" class="filter-trigger" id="regionFilterButton" aria-haspopup="true" aria-expanded="false" aria-controls="regionFilterMenu">Region</button>\n        <div class="filter-menu hidden" id="regionFilterMenu" role="group" aria-label="Region options"></div>\n      </div>\n      <div class="multi-filter" id="pseStatusFilter" data-filter-title="PSE Status" data-filter-key="pseStatus" data-filter-label="PSE statuses">\n        <button type="button" class="filter-trigger" id="pseStatusFilterButton" aria-haspopup="true" aria-expanded="false" aria-controls="pseStatusFilterMenu">PSE Status</button>\n        <div class="filter-menu hidden" id="pseStatusFilterMenu" role="group" aria-label="PSE Status options"></div>\n      </div>\n      <span class="spacer"></span><span id="filterCount" class="sub"></span>\n    </div>\n    <section id="panelUpdate">\n      <h2>PSE to update</h2>\n      <div id="bulkBar" class="bulk-bar">\n        <div class="bulk-info"><span id="bulkCount">0</span> Opps need a PSE field, Team, or Split update</div>\n        <button id="updateAllBtn">Update all 0 in Salesforce →</button><span id="bulkMsg" class="msg"></span>\n      </div>\n      <div id="actionList" class="action-list"></div>\n      <div id="actionEmpty" class="empty hidden">No Opportunities need a PSE field, Team, or Split update for these filters.</div>\n      <div class="pagination"><span id="actionPageInfo"></span><button class="ghost" id="actionPrev">Previous</button><button class="ghost" id="actionNext">Next</button></div>\n    </section>\n    <footer class="sub">Commissionable Renewal, New Business, and Expansion Opportunities at Stage 08 - Closed with a tagged Partner and a PSE missing from the Team, Splits, or both. When the PSE field is blank, membership checks use the Partner Owner. Existing PSE values and existing Team and Split entries are preserved. Refresh reads Salesforce; Update actions apply the process after confirmation.</footer>\n  </section>\n</main>\n\n<dialog id="processFlow" class="process-page" aria-labelledby="processTitle">\n  <div class="process-bar"><div class="process-brand">PSE Split Automation</div><button id="closeProcessFlow" class="ghost" autofocus>Close · Back to dashboard ×</button></div>\n  <div class="process-content">\n    <div class="process-intro"><h2 id="processTitle">Process Flow</h2><p>How the dashboard works</p></div>\n    <p class="process-scope"><b>Filter:</b> Closed Opportunity · With Partner Tagged · Stage: 08 - Closed</p>\n    <section class="flow-step"><h3><span class="step-number">1</span> Does the closed Opportunity have a Partner tagged?</h3>\n      <p>Start with Opportunities whose Stage is exactly <b>08 - Closed</b>. Check whether the closed Opportunity has a tagged <b>Partner</b>.</p>\n      <div class="branches"><div class="branch"><strong>Partner is tagged → Continue</strong><p>Use the tagged Partner for this process.</p></div><div class="branch"><strong>No Partner → Stop</strong><p>Skip this Opportunity. It does not appear in the worklist.</p></div></div>\n      <p class="also">Salesforce field: the lookup labeled “Partner” is <code>Referring_Partner__c</code>.</p>\n    </section><div class="flow-arrow" aria-hidden="true">↓</div>\n    <section class="flow-step"><h3><span class="step-number">2</span> Choose the Partner Sales Rep</h3>\n      <div class="branches"><div class="branch"><strong>PSE already populated → Use existing rep</strong><p>Keep <code>Partner_Sales_Rep__c</code> exactly as it is, even if the Partner has a different Owner.</p></div><div class="branch"><strong>PSE blank → Use the Partner’s Owner</strong><p>When you click Update, populate <code>Partner_Sales_Rep__c</code> with the Owner of the tagged Partner.</p></div></div>\n      <p class="process-note"><b>Key rule:</b> Populate the PSE field only when blank. Both paths continue to the Team check, then the Splits check.</p>\n    </section><div class="flow-arrow" aria-hidden="true">↓</div>\n    <section class="flow-step"><h3><span class="step-number">3</span> Check the Opportunity Team</h3>\n      <div class="branches"><div class="branch"><strong>Rep already on the Team → Keep entry</strong><p>Make no Team change. Continue to Opportunity Splits.</p></div><div class="branch"><strong>Rep missing → Add Team member</strong><dl><dt>User</dt><dd>Chosen PSE</dd><dt>Team Role</dt><dd>Partner Account Executive</dd><dt>Opportunity Access</dt><dd>Read Only</dd></dl></div></div>\n    </section><div class="flow-arrow" aria-hidden="true">↓</div>\n    <section class="flow-step"><h3><span class="step-number">4</span> Check Opportunity Splits</h3>\n      <div class="branches"><div class="branch"><strong>Rep already on a Split → Keep entry</strong><p>Make no Split change. Any existing Split for that rep counts as present; its type, role, and percentage stay as they are.</p></div><div class="branch"><strong>Rep missing → Add Overlay Split</strong><dl><dt>Split Owner</dt><dd>Chosen PSE</dd><dt>Split Type</dt><dd>Overlay</dd><dt>Team Role</dt><dd>Partner Account Executive</dd><dt>Percent</dt><dd>100.00%</dd></dl></div></div>\n    </section>\n    <section class="process-help"><h3>Using the dashboard</h3>\n      <p>The list shows closed Opportunities with a Partner tagged where the PSE still needs to be added to the Opportunity Team, Opportunity Splits, or both. When the PSE field is blank, these checks use the tagged Partner’s Owner.</p>\n      <div data-hosted-upload class="hidden"><h4>Upload the data</h4><p>First time downloading the data? <button type="button" id="firstTimeProcessLink" class="text-link">View first-time setup instructions</button>. The guide includes a prompt for your Codex and the manual upload steps. Closing the guide takes you to Upload the data.</p><p>Run the local Salesforce export command, then click <b>Upload the data</b> and choose the generated <b>pse-data.json</b>. Uploading replaces the shared saved snapshot. Opening or reloading this dashboard shows the last uploaded file; Google Drive changes are not imported automatically.</p><p>Use the local dashboard for Salesforce updates. The hosted dashboard supports the worklist, filters, and CSV export.</p></div><div data-local-actions><h4>Refresh</h4>\n      <p>Click <b>Refresh</b> to pull the latest data from Salesforce. The dashboard updates its counts and list based on the current Opportunity, Partner, PSE, Team, and Split records in SFDC. Data refreshes only when this button is clicked. Opening or reloading the page shows the last saved data.</p>\n      </div><h4>Clickable boxes</h4>\n      <p>Click a box to filter the list by category:</p>\n      <ol>\n        <li><b>Opportunities with tagged PSE:</b> Closed Opportunities with a Partner and an existing PSE, where that PSE is missing from the Opportunity Team, Opportunity Splits, or both.</li>\n        <li><b>Partner but no tagged PSE:</b> Closed Opportunities with a Partner but a blank PSE field, where the Partner’s Owner is missing from the Opportunity Team, Opportunity Splits, or both. The Owner is the PSE that will be used when you click Update.</li>\n        <li><b>All Opportunities to update:</b> Combines the first two categories: closed Opportunities with a Partner, with or without a tagged PSE, that still need a Team or Split update.</li>\n      </ol>\n      <p><b>What “missing” means:</b> If the rep is already on the Team but has no Split, the Opportunity stays in the list. The same applies if the rep has a Split but is missing from the Team. If the rep is already on both, the Opportunity is excluded from all three boxes.</p>\n      <h4>Search and filters</h4>\n      <p>Search by <b>Opportunity name, Opportunity ID, or Account name</b>. Use the filters below to narrow the selected category. You can select multiple values in each filter; selections across different filters work together. Clear a filter’s selections to remove that restriction.</p>\n      <dl class="help-filters">\n        <dt>Fiscal Quarter–Year</dt><dd>Filters by Opportunity Close Date using Zendesk’s fiscal calendar: Q1 Feb–Apr, Q2 May–Jul, Q3 Aug–Oct, and Q4 Nov–Jan. For example, November 2026 through January 2027 is FY2027 Q4.</dd>\n        <dt>Opportunity Type</dt><dd>Choose Renewal, New Business, Expansion, or a combination.</dd>\n        <dt>Market Segment</dt><dd>Filters by the Opportunity’s Account Owner Market Segment.</dd>\n        <dt>Region</dt><dd>Filters by the Region recorded on the Opportunity.</dd>\n        <dt>PSE Status</dt><dd>Choose Active, Inactive, or both. If a PSE is tagged, this is that user’s status. If the PSE field is blank, this is the Partner Owner’s status.</dd>\n      </dl>\n      <p>The box counts reflect your search and filters. <b>All Opportunities to update = tagged PSE category + no tagged PSE category</b> for the same selections.</p>\n      <div data-local-actions><h4>Update and export</h4>\n      <p><b>Update in Salesforce</b> applies the process to one Opportunity after confirmation. <b>Update all N in Salesforce</b> applies it to all matching results across all pages, using your selected box, search, and filters. <b>Export CSV</b> downloads that same filtered list.</p>\n      <p>Refresh only reads Salesforce. Update actions preserve an existing PSE, populate a blank PSE from the tagged Partner’s Owner, and add missing Team and Split entries. Each Opportunity uses its own PSE. Existing entries are preserved; Salesforce errors are reported so you can retry the remaining steps.</p>\n      </div><p><b>Scope:</b> Commissionable Renewal, New Business, and Expansion Opportunities at Stage exactly <b>08 - Closed</b>, with a Partner tagged.</p>\n    </section>\n  </div>\n</dialog>\n<dialog id="uploadPage" class="process-page" aria-labelledby="uploadTitle">\n  <div class="process-bar"><div class="process-brand">PSE Split Automation</div><button id="closeUploadPage" class="ghost" autofocus>Close · Back to dashboard ×</button></div>\n  <div class="process-content">\n    <div class="process-intro"><h2 id="uploadTitle">Upload the data</h2><p>Load your Salesforce export into the dashboard</p></div>\n    <section class="process-help">\n      <h3>First time here?</h3>\n      <p><button type="button" id="firstTimeUploadLink" class="text-link">View first-time setup instructions</button> to set up the download using your own Salesforce account. The guide includes a ready-to-copy Codex prompt. Close the guide to return here.</p>\n      <h3>1 · Ask Codex to download fresh data</h3>\n      <p>Open Codex on your computer. Copy the prompt below, paste it into your Codex chat, and send it. Codex will use your own Salesforce account to download the latest data into your synced Google Drive folder.</p>\n      <div class="setup-actions"><button type="button" id="copyDownloadPrompt">Copy download prompt</button><span id="copyDownloadMsg" class="sub" role="status" aria-live="polite"></span></div>\n      <textarea id="downloadPrompt" class="setup-prompt" readonly aria-label="Codex download prompt">Download the latest PSE Split Automation data from Salesforce into our shared Google Drive folder.\n\nUse this public repository:\nhttps://github.com/justinemendez-svg/PSE-Split-Automation\n\nLocate my existing clone and read its export instructions. Use MY OWN Salesforce CLI account. If my session has expired, guide me through Salesforce/Okta sign-in.\n\nFind MY locally synced Google Drive folder for:\nShared drives/GTM Ops/MSS/PSE_Split_Automation\n\nUse the actual folder path on my computer, not Justine’s username or local path. Confirm I can write to the shared folder. If the repository or access is missing, explain what setup I need.\n\nFrom the repository folder, run:\npython3 export_for_upload.py --org prod --export-dir &quot;&lt;MY_ACTUAL_SYNCED_FOLDER_PATH&gt;&quot;\n\nReplace the placeholder with my actual synced folder path before running. Pull fresh Salesforce data; do not reuse an old snapshot. Preserve the repository’s scope and classification rules.\n\nVerify the export completed successfully and pse-data.json was saved in that Google Drive folder. Report the extraction date, Opportunity count, and full file path so I can choose it for upload. Tell me to wait for Google Drive to finish syncing.\n\nDo not modify Salesforce records, upload anything to AppFoundry, commit exported data to GitHub, or schedule automatic downloads. I will upload pse-data.json to the dashboard manually.</textarea>\n      <p>Wait for Codex to confirm the download succeeded and show the extraction date, Opportunity count, and full file path. Wait for Google Drive to finish syncing before choosing the file below:</p>\n      <p style="overflow-wrap:anywhere"><code>GTM Ops/MSS/PSE_Split_Automation/pse-data.json</code></p>\n      <h3>2 · Choose the exported file</h3>\n      <p>Select <b>pse-data.json</b> from that folder. Use the complete JSON export; the dashboard’s filtered CSV export cannot be uploaded here. Maximum size: 25 MB.</p>\n      <input id="uploadFile" type="file" accept=".json,application/json" aria-label="Salesforce dashboard data file" />\n      <h3>3 · Upload to the dashboard</h3>\n      <p>This replaces the saved data for everyone using this AppFoundry dashboard. It does not update Salesforce. To show later Salesforce changes, send the download prompt to Codex again, then manually upload the new file.</p>\n      <button id="confirmUploadBtn" disabled>Upload data to dashboard</button>\n      <p id="uploadMsg" class="msg" role="status" aria-live="polite">Choose pse-data.json to preview the extraction date and record count.</p>\n      <p>Close this page or press Escape to return to the dashboard. Your search and filters are preserved where available in the uploaded data.</p>\n    </section>\n  </div>\n</dialog>\n<dialog id="setupInstructions" class="process-page" aria-labelledby="setupTitle">\n  <div class="process-bar"><div class="process-brand">PSE Split Automation</div><button id="closeSetupInstructions" class="ghost" autofocus>Close · Back to Upload ×</button></div>\n  <div class="process-content">\n    <div class="process-intro"><h2 id="setupTitle">First-time setup instructions</h2><p>Set up your Salesforce download once, then upload fresh data manually</p></div>\n    <section class="process-help">\n      <h3>Before you start</h3>\n      <p>You need your own Salesforce account with API access and permission to read the required records, Google Drive for desktop with <b>GTM Ops/MSS/PSE_Split_Automation</b> synced and writable, and Codex running on your computer. The repository is public: <a href="https://github.com/justinemendez-svg/PSE-Split-Automation" target="_blank" rel="noopener">PSE-Split-Automation on GitHub</a>.</p>\n      <h3>1 · Paste this prompt into your Codex</h3>\n      <p>To set up the download to Google Drive, copy the complete prompt below, paste it into a new Codex chat on your computer, and send it. Follow any installation or Salesforce/Okta sign-in steps Codex shows you. Each person must use their own account and local folder path.</p>\n      <div class="setup-actions"><button type="button" id="copySetupPrompt">Copy Codex prompt</button><span id="copySetupMsg" class="sub" role="status" aria-live="polite"></span></div>\n      <textarea id="setupPrompt" class="setup-prompt" readonly aria-label="Codex setup prompt">Set up the PSE Split Automation Salesforce data export on my computer using this public repository:\n\nhttps://github.com/justinemendez-svg/PSE-Split-Automation\n\nClone the repo, or pull the latest version if it already exists. Read its setup instructions and check that Python 3, Git, and Salesforce CLI are installed.\n\nUse MY OWN Salesforce account and CLI session. If login is needed, guide me through Salesforce/Okta authentication using:\n\nsf org login web --alias prod --instance-url https://zendesk.my.salesforce.com\n\nLocate MY locally synced Google Drive folder corresponding to:\n\nShared drives/GTM Ops/MSS/PSE_Split_Automation\n\nDiscover the actual path on my computer—do not use Justine’s username or assume her local path exists. If the shared folder is unavailable or I cannot write to it, explain the missing access before continuing.\n\nRun the repository’s read-only export command using my Salesforce account and the discovered folder:\n\npython3 export_for_upload.py --org prod --export-dir &quot;&lt;MY_ACTUAL_SYNCED_FOLDER_PATH&gt;&quot;\n\nThis must download the latest Salesforce data and save/replace pse-data.json in that same shared Google Drive folder. Preserve the repository’s existing scope and classification rules.\n\nVerify that the export completed successfully, the JSON passes the repository’s validation, and the file exists in the correct folder. Report its extraction date, Opportunity count, and full path.\n\nDo not modify Salesforce records, commit exported data to GitHub, schedule automatic refreshes, or upload the file to AppFoundry. The AppFoundry upload will be done manually.\n\nFinally, give me the exact command to reuse whenever I want to refresh the Google Drive data.</textarea>\n      <h3>2 · Check the downloaded file</h3>\n      <p>Wait for Codex to confirm the export succeeded. It should report the extraction date, Opportunity count, and full path to <b>pse-data.json</b> in your synced <b>PSE_Split_Automation</b> folder. Wait for Google Drive to finish syncing. Keep the exact reusable export command Codex gives you.</p>\n      <h3>3 · Upload the file manually</h3>\n      <ol>\n        <li>Click <b>Close · Back to Upload</b> at the top of this guide. You will return to <b>Upload the data</b>.</li>\n        <li>Choose <b>pse-data.json</b> from your synced <b>GTM Ops/MSS/PSE_Split_Automation</b> folder. Use JSON, not the dashboard’s Export CSV file. Maximum size: 25 MB.</li>\n        <li>Check the extraction date and record count shown in the preview, then click <b>Upload data to dashboard</b>.</li>\n        <li>Wait for <b>Upload complete</b>, then click <b>Close · Back to dashboard</b> to view the updated counts and list.</li>\n      </ol>\n      <h3>Next time you need fresh data</h3>\n      <p>Return to Upload the data, copy the download prompt into your Codex chat, and wait for the export and Google Drive sync to finish. Then repeat the manual upload steps above. First-time setup is only needed again if your computer, Salesforce access, or Drive folder changes.</p>\n      <p><b>What changes:</b> the command reads Salesforce and replaces the shared Google Drive export. Uploading replaces the saved data for everyone using this dashboard. Neither step updates Salesforce records. There are no scheduled downloads or automatic uploads.</p>\n      <p>Pressing Escape also closes this guide and returns you to the Upload page.</p>\n    </section>\n  </div>\n</dialog>\n<script src="app.js"></script>\n</body>\n</html>\n'
APP_JS = '/* Partner → PSE field → Opportunity Team → Opportunity Splits. */\nconst SF_LIGHTNING_URL = "https://zendesk.lightning.force.com";\nconst TEAM_ROLE = "Partner Account Executive";\nconst SPLIT_TYPE = "Overlay";\nconst SPLIT_PERCENTAGE = 100;\nconst PAGE_SIZE = 100;\nconst OPPORTUNITY_TYPES = ["Renewal", "New Business", "Expansion"];\nconst SCOPE_VERSION = 4;\nconst CLOSED_STAGE = "08 - Closed";\nconst state = {\n  rows: [], rowsById: new Map(), summary: {}, type: new Set(), segment: new Set(), region: new Set(), pseStatus: new Set(), fiscalQuarter: new Set(),\n  filterOptions: { type: OPPORTUNITY_TYPES, segment: [], region: [], pseStatus: [], fiscalQuarter: [] }, query: "",\n  sortKey: "closeDate", sortDir: -1, updatePage: 1, pseCategory: "all", busy: false,\n  writeApi: { enabled: false, refreshEnabled: false, org: null, authMode: "local", loggedIn: true },\n};\nconst $ = (id) => document.getElementById(id);\nlet wired = false;\nlet searchTimer = null;\n\nfunction esc(value) {\n  return String(value == null ? "" : value).replace(/[&<>"\']/g, (ch) =>\n    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;" }[ch]));\n}\nfunction fmtDate(value) {\n  if (!value) return "—";\n  const date = new Date(value + "T00:00:00");\n  return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString("en-US", { day: "numeric", month: "short", year: "numeric" });\n}\nfunction fiscalQuarterFromDate(value) {\n  const match = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(value || ""));\n  if (!match) return "Close date unavailable";\n  const [, yearText, monthText, dayText] = match;\n  const year = Number(yearText), month = Number(monthText), day = Number(dayText);\n  const date = new Date(Date.UTC(year, month - 1, day));\n  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return "Close date unavailable";\n  const fiscalYear = month >= 2 ? year + 1 : year;\n  const quarter = Math.floor(((month + 10) % 12) / 3) + 1;\n  return "FY" + fiscalYear + " Q" + quarter;\n}\n\nfunction fmtCount(value) { return Number(value || 0).toLocaleString("en-US"); }\nfunction detailsLine(row) {\n  return [row.id, row.stage, fmtDate(row.closeDate), row.type].filter(Boolean).join(" · ");\n}\nfunction accountLine(row) {\n  return [row.account, row.accountOwner, row.segment, row.region].filter(Boolean).join(" · ") || "—";\n}\n\nasync function load() {\n  wire();\n  try {\n    const response = await fetch("pse-data.json?_=" + Date.now(), { cache: "no-store" });\n    if (!response.ok) {\n      const details = await response.json().catch(() => ({}));\n      await detectApi();\n      const status = $("status");\n      if (details.error) {\n        status.className = "status err";\n        status.textContent = "Dashboard data could not be loaded: " + details.error + " (HTTP " + response.status + "). Check the server configuration, then reload.";\n        return;\n      }\n      status.className = state.writeApi.refreshEnabled ? "status" : "status err";\n      status.textContent = state.writeApi.refreshEnabled\n        ? "No Salesforce snapshot yet. Click Refresh to load data."\n        : "Dashboard data is unavailable (HTTP " + response.status + "). Check the server configuration, then reload.";\n      return;\n    }\n    const data = await response.json();\n    hydrate(data);\n    await detectApi();\n  } catch (error) {\n    await detectApi();\n    const status = $("status");\n    status.className = state.writeApi.refreshEnabled ? "status" : "status err";\n    status.textContent = state.writeApi.refreshEnabled\n      ? "Dashboard snapshot could not be loaded. Click Refresh to fetch it from Salesforce. (" + error.message + ")"\n      : window.location.protocol === "file:"\n        ? "Open the dashboard through its local server. Double-click serve.command, then open http://localhost:8773 in Chrome."\n        : "Dashboard data could not be loaded. Check the server connection, then reload. (" + error.message + ")";\n  }\n}\n\nfunction renderFilter(id, key, values) {\n  const component = $(id);\n  const selected = state[key];\n  const available = new Set(values);\n  state[key] = new Set([...selected].filter((value) => available.has(value)));\n  state.filterOptions[key] = values;\n  const choices = state[key];\n  const label = component.dataset.filterLabel;\n  const button = $(id + "Button");\n  button.textContent = !choices.size || choices.size === values.length\n    ? component.dataset.filterTitle\n    : choices.size === 1 ? [...choices][0] : choices.size + " " + label + " selected";\n  const menu = $(id + "Menu");\n  menu.innerHTML = values.map((value) =>\n    \'<label class="filter-option"><input type="checkbox" data-filter-option value="\' + esc(value) + \'"\' +\n    (choices.has(value) ? " checked" : "") + \'><span>\' + esc(value) + \'</span></label>\').join("") +\n    \'<div class="filter-actions"><button type="button" data-filter-select-all>Select all</button>\' +\n    \'<button type="button" data-filter-clear>Clear</button></div>\';\n}\n\nfunction hydrate(data) {\n  wire();\n  state.generatedAt = data.generatedAt;\n  if ((data.config || {}).scopeVersion !== SCOPE_VERSION) {\n    state.rows = [];\n    state.rowsById.clear();\n    $("dashboard").classList.add("hidden");\n    const status = $("status");\n    status.className = "status";\n    status.textContent = "The closed Opportunity flow (08 - Closed) needs a fresh Salesforce snapshot. Load a current export using Upload the data, or click Refresh in the local app.";\n    return false;\n  }\n  state.rows = (data.rows || []).map((row) => ({ ...row, fiscalQuarter: fiscalQuarterFromDate(row.closeDate) }));\n  state.rowsById = new Map(state.rows.map((row) => [row.id, row]));\n  state.summary = data.summary || {};\n  const generated = data.generatedAt ? new Date(data.generatedAt) : null;\n  $("who").textContent = generated ? "Refreshed " + generated.toLocaleString() : "";\n  renderFilter("pseStatusFilter", "pseStatus", ["Active", "Inactive", ...(state.rows.some((row) => row.partnerRepActive !== true && row.partnerRepActive !== false) ? ["Status unavailable"] : [])]);\n  renderFilter("quarterFilter", "fiscalQuarter", [...new Set(state.rows.map((row) => row.fiscalQuarter))].sort((a, b) => b.localeCompare(a)));\n  renderFilter("typeFilter", "type", OPPORTUNITY_TYPES);\n  renderFilter("segmentFilter", "segment", [...new Set(state.rows.map((row) => row.segment).filter(Boolean))].sort());\n  renderFilter("regionFilter", "region", [...new Set(state.rows.map((row) => row.region).filter(Boolean))].sort());\n  $("status").classList.add("hidden");\n  $("dashboard").classList.remove("hidden");\n  render();\n  return true;\n}\n\nasync function detectApi() {\n  try {\n    const response = await fetch("/api/health", { cache: "no-store" });\n    if (!response.ok) return;\n    const health = await response.json();\n    state.writeApi.enabled = !!health.writeEnabled;\n    state.writeApi.refreshEnabled = !!health.refreshEnabled;\n    state.writeApi.org = health.org || "default";\n    state.writeApi.authMode = health.authMode || "local";\n    state.writeApi.loggedIn = state.writeApi.authMode !== "oauth" || !!health.loggedIn;\n    $("refreshBtn").classList.toggle("hidden", !health.refreshEnabled);\n    state.writeApi.uploadEnabled = !!health.uploadEnabled;\n    $("uploadDataBtn").classList.toggle("hidden", !health.uploadEnabled);\n    document.querySelectorAll("[data-hosted-upload]").forEach(node => node.classList.toggle("hidden", !health.uploadEnabled));\n    document.querySelectorAll("[data-local-actions]").forEach(node => node.classList.toggle("hidden", !!health.uploadEnabled));\n    $("updateAllBtn").classList.toggle("hidden", !!health.uploadEnabled);\n    if (health.uploadEnabled && !state.generatedAt) {\n      $("status").className = "status";\n      $("status").textContent = "No data uploaded yet. Click Upload the data to load your Salesforce export.";\n      $("dashboard").classList.add("hidden");\n    }\n    $("who").textContent = $("who").textContent.split(" · Salesforce org:")[0];\n    if (state.writeApi.enabled) $("who").textContent += " · Salesforce org: " + state.writeApi.org;\n    renderUpdate();\n  } catch (_) { /* Static hosting has no local Salesforce API. */ }\n}\n\nfunction pseStatus(row) { return row.partnerRepActive === true ? "Active" : row.partnerRepActive === false ? "Inactive" : "Status unavailable"; }\n\nfunction rowComplete(row) { return !row.partnerRepNeedsPopulate && row.partnerRepOnTeam && row.partnerRepOnSplit; }\n\nfunction matchesCategory(row, category) {\n  const missingMembership = !row.partnerRepOnTeam || !row.partnerRepOnSplit;\n  if (category === "tagged") return !row.partnerRepNeedsPopulate && missingMembership;\n  if (category === "untagged") return !!row.partnerRepNeedsPopulate && missingMembership;\n  return missingMembership;\n}\n\nfunction filteredRows(category = state.pseCategory) {\n  let rows = state.rows.filter((row) => row.inScope !== false && row.nonCommissionable === false && row.stage === CLOSED_STAGE &&\n    OPPORTUNITY_TYPES.includes(row.type) && row.partnerId && !rowComplete(row));\n  ["type", "segment", "region", "pseStatus", "fiscalQuarter"].forEach((key) => {\n    const selected = state[key];\n    const options = state.filterOptions[key];\n    if (selected.size && selected.size < options.length) rows = rows.filter((row) => selected.has(key === "pseStatus" ? pseStatus(row) : row[key]));\n  });\n  if (state.query) {\n    const q = state.query;\n    rows = rows.filter((row) => [row.name, row.account, row.id, row.accountOwner, row.partnerRepName]\n      .some((value) => String(value == null ? "" : value).toLowerCase().includes(q)));\n  }\n  rows = rows.filter((row) => matchesCategory(row, category));\n  const key = state.sortKey;\n  return [...rows].sort((a, b) => {\n    const av = a[key] == null ? "" : a[key];\n    const bv = b[key] == null ? "" : b[key];\n    const compare = typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv), undefined, { numeric: true, sensitivity: "base" });\n    return compare * state.sortDir;\n  });\n}\n\nfunction opportunityCard(row) {\n  const href = SF_LIGHTNING_URL + "/lightning/r/Opportunity/" + encodeURIComponent(row.id) + "/view";\n  const button = state.writeApi.enabled\n    ? \'<button class="btn-update" data-update="\' + esc(row.id) + \'"\' + ((state.busy || row.blockedReason) ? \' disabled\' : \'\') + \'>Update in Salesforce →</button>\'\n    : \'<a class="btn-update" href="\' + esc(href) + \'" target="_blank" rel="noopener">Open in Salesforce →</a>\';\n  const teamAlready = row.partnerRepOnTeam\n    ? \'<div class="also">Already on the Opportunity Team — no change needed.</div>\' : \'\';\n  const splitAlready = row.partnerRepOnSplit\n    ? \'<div class="also">Rep already on Opportunity Splits — existing entry preserved.</div>\' : \'\';\n  const userStatus = row.partnerRepActive === true ? \'Active\' : row.partnerRepActive === false ? \'Inactive\' : \'Status unavailable\';\n  return \'<article class="action-card needs-update" data-card="\' + esc(row.id) + \'">\' +\n    \'<div class="action-head"><div class="head-main">\' +\n    \'<div class="opp-title"><a href="\' + esc(href) + \'" target="_blank" rel="noopener">\' + esc(row.name || "Unnamed Opportunity") + \'</a></div>\' +\n    \'<div class="details-line">\' + esc(detailsLine(row)) + \'</div>\' +\n    \'<div class="details-line account-name">\' + esc(accountLine(row)) + \'</div>\' +\n    \'<div class="details-line">Partner: \' + esc(row.partnerName || "—") + \' · Partner Owner: \' + esc(row.partnerOwnerName || "—") + \'</div>\' +\n    \'<div class="pse-tag"><b>\' + (row.partnerRepNeedsPopulate ? \'PSE to populate\' : \'PSE Tagged\') + \'</b><span class="pse-name">\' + esc(row.partnerRepName || "—") + \'</span><span class="pill\' + (row.partnerRepActive !== true ? \' warn\' : \'\') + \'">\' + userStatus + \'</span></div>\' +\n    (row.blockedReason ? \'<div class="msg err">\' + esc(row.blockedReason) + \'</div>\' : \'\') +\n    \'<div class="msg" data-msg="\' + esc(row.id) + \'"></div></div>\' + button + \'</div>\' +\n    \'<div class="action-steps">\' +\n      \'<section class="step"><div class="step-title">1 · Partner Sales Rep field</div>\' +\n        \'<div class="step-path">\' + (row.partnerRepNeedsPopulate ? \'Populate from the tagged Partner’s Owner\' : \'Preserve the existing PSE\') + \'</div>\' +\n        \'<table class="step-values"><tbody><tr><td>PSE</td><td>\' + esc(row.partnerRepName) + \'</td></tr><tr><td>Action</td><td>\' +\n        (row.partnerRepNeedsPopulate ? \'Populate blank field\' : \'No field change\') + \'</td></tr></tbody></table></section>\' +\n      \'<section class="step"><div class="step-title">2 · Check Opportunity Team</div>\' +\n        \'<div class="step-path">Opportunity → Opportunity Team → Add Members</div>\' +\n        \'<table class="step-values"><tbody>\' +\n          \'<tr><td>User</td><td>\' + esc(row.partnerRepName || "—") + \'</td></tr>\' +\n          \'<tr><td>Team Role</td><td>\' + esc(TEAM_ROLE) + \'</td></tr>\' +\n          \'<tr><td>Opportunity Access</td><td>Read Only</td></tr>\' +\n        \'</tbody></table>\' + teamAlready + \'</section>\' +\n      \'<section class="step"><div class="step-title">3 · Check Opportunity Splits</div>\' +\n        \'<div class="step-path">Opportunity → Opportunity Splits → Edit Splits</div>\' +\n        \'<table class="step-values"><tbody>\' +\n          \'<tr><td>Split Owner</td><td>\' + esc(row.partnerRepName || "—") + \'</td></tr>\' +\n          \'<tr><td>Split Type</td><td>\' + esc(SPLIT_TYPE) + \'</td></tr>\' +\n          \'<tr><td>Team Role</td><td>\' + esc(TEAM_ROLE) + \'</td></tr>\' +\n          \'<tr><td>Percent</td><td>100.00%</td></tr>\' +\n        \'</tbody></table>\' + splitAlready + \'</section>\' +\n    \'</div></article>\';\n}\n\nfunction wireCardUpdates(containerId) {\n  $(containerId).querySelectorAll("button[data-update]").forEach((button) =>\n    button.addEventListener("click", () => updateOne(button.dataset.update, button)));\n}\n\nfunction renderUpdate() {\n  const allRows = filteredRows("all");\n  const rows = allRows.filter((row) => matchesCategory(row, state.pseCategory));\n  $("cWithPse").textContent = fmtCount(allRows.filter((row) => matchesCategory(row, "tagged")).length);\n  $("cWithoutPse").textContent = fmtCount(allRows.filter((row) => matchesCategory(row, "untagged")).length);\n  $("cNeedsUpdate").textContent = fmtCount(allRows.length);\n  document.querySelectorAll("[data-pse-category]").forEach((button) => {\n    const selected = button.dataset.pseCategory === state.pseCategory;\n    button.classList.toggle("selected", selected);\n    button.setAttribute("aria-pressed", String(selected));\n  });\n  $("categoryLabel").textContent = {\n    all: "Showing all Opportunities to update",\n    tagged: "Showing Partner Opportunities with a tagged PSE · missing Team or Split",\n    untagged: "Showing Partner Opportunities without a tagged PSE · missing Team or Split",\n  }[state.pseCategory];\n  const pageCount = Math.max(1, Math.ceil(rows.length / PAGE_SIZE));\n  state.updatePage = Math.min(state.updatePage, pageCount);\n  const start = (state.updatePage - 1) * PAGE_SIZE;\n  $("bulkCount").textContent = rows.length.toLocaleString();\n  $("updateAllBtn").textContent = "Update all " + rows.length.toLocaleString() + " in Salesforce →";\n  $("updateAllBtn").disabled = state.busy || !state.writeApi.enabled || rows.length === 0;\n  $("actionList").innerHTML = rows.slice(start, start + PAGE_SIZE).map((row) => opportunityCard(row)).join("");\n  wireCardUpdates("actionList");\n  $("actionPageInfo").textContent = rows.length ? `Page ${state.updatePage} of ${pageCount}` : "";\n  $("filterCount").textContent = fmtCount(rows.length) + " Opportunities to update";\n  $("actionPrev").disabled = state.busy || state.updatePage <= 1;\n  $("actionNext").disabled = state.busy || state.updatePage >= pageCount;\n  $("actionEmpty").classList.toggle("hidden", rows.length > 0);\n  $("actionList").classList.toggle("hidden", rows.length === 0);\n}\n\nfunction render() {\n  renderUpdate();\n}\n\nasync function postJson(path, body) {\n  const response = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });\n  let result;\n  try { result = await response.json(); }\n  catch (_) { throw new Error(path === "/api/upload"\n    ? "The upload response could not be read."\n    : "The server response could not be read. Check Salesforce status before retrying an update."); }\n  if (response.status === 401 || result.needsLogin) state.writeApi.loggedIn = false;\n  if (!response.ok) {\n    const error = new Error(result.error || ("HTTP " + response.status));\n    error.status = response.status;\n    throw error;\n  }\n  return result;\n}\n\nfunction ensureWriteLogin() { return Promise.resolve(true); }\n\nlet selectedUpload = null;\nlet uploadPreviewVersion = 0;\nasync function previewUpload(file) {\n  if (state.busy) return;\n  const version = ++uploadPreviewVersion;\n  selectedUpload = null;\n  $("confirmUploadBtn").disabled = true;\n  const message = $("uploadMsg");\n  if (!file) { message.textContent = "Choose pse-data.json from the PSE_Split_Automation folder."; return; }\n  try {\n    if (file.size > 25 * 1024 * 1024) throw new Error("Maximum file size is 25 MB.");\n    const value = JSON.parse(await file.text());\n    if (version !== uploadPreviewVersion) return;\n    if (!value || value.config?.scopeVersion !== SCOPE_VERSION || !Array.isArray(value.rows) ||\n        !value.generatedAt || Number.isNaN(new Date(value.generatedAt).getTime()))\n      throw new Error("Choose pse-data.json generated by the latest local Salesforce export command.");\n    selectedUpload = value;\n    message.className = "msg";\n    message.textContent = fmtCount(value.rows.length) + " Opportunities in file · Extracted " + new Date(value.generatedAt).toLocaleString() + ". Click Upload data to dashboard to replace the saved data.";\n    $("confirmUploadBtn").disabled = false;\n  } catch (error) {\n    if (version !== uploadPreviewVersion) return;\n    message.className = "msg err"; message.textContent = error.message;\n  }\n}\n\nasync function uploadData() {\n  if (!selectedUpload || state.busy) return;\n  setBusy(true);\n  $("confirmUploadBtn").disabled = true;\n  $("uploadFile").disabled = true;\n  $("uploadMsg").className = "msg";\n  $("uploadMsg").textContent = "Validating and saving the uploaded data…";\n  try {\n    const result = await postJson("/api/upload", { manual: true, snapshot: selectedUpload });\n    hydrate(result.snapshot);\n    $("uploadMsg").className = "msg ok";\n    $("uploadMsg").textContent = "Upload complete. The dashboard now shows this Salesforce export. Close this page to view it.";\n  } catch (error) {\n    $("uploadMsg").className = "msg err";\n    $("uploadMsg").textContent = error.message + ([400, 413].includes(error.status)\n      ? " The file was rejected; the previous saved data was kept."\n      : " Upload status could not be confirmed. Close this page and reload the dashboard to check the saved extraction date before retrying.");\n  } finally {\n    setBusy(false);\n    $("confirmUploadBtn").disabled = false;\n    $("uploadFile").disabled = false;\n  }\n}\n\nfunction setRowState(oppId, value) {\n  const row = state.rowsById.get(oppId);\n  if (!row) return;\n  const wasComplete = !!rowComplete(row);\n  Object.assign(row, value);\n  const change = Number(!!rowComplete(row)) - Number(wasComplete);\n  state.summary.tagged = (state.summary.tagged || 0) + change;\n  state.summary.needsUpdate = (state.summary.needsUpdate || 0) - change;\n\n}\n\nfunction setBusy(value) {\n  state.busy = value;\n  document.querySelectorAll(\'#search, .filter-trigger, .filter-menu input, .filter-actions button, [data-pse-category], #actionPrev, #actionNext, #csvBtn, #refreshBtn, #updateAllBtn, button[data-update]\').forEach((control) => { control.disabled = value; });\n  if (!value) renderUpdate();\n}\n\nasync function updateOne(oppId, button) {\n  if (state.busy) return;\n  setBusy(true);\n  button.disabled = true;\n  let message = document.querySelector(\'[data-msg="\' + CSS.escape(oppId) + \'"]\');\n  message.textContent = "Checking Salesforce…";\n  message.className = "msg";\n  try {\n    if (!(await ensureWriteLogin())) throw new Error("Salesforce login is required before updating.");\n    const preview = await postJson("/api/preview", { oppId });\n    setRowState(oppId, preview);\n    if (preview.alreadyComplete) {\n      setRowState(oppId, preview); renderUpdate(); return;\n    }\n    if (!preview.eligible) throw new Error(preview.reason || "This PSE is no longer eligible.");\n    const okay = window.confirm(\n      "Apply the Partner → PSE → Team → Splits process for:\\n\\n" + preview.oppName +\n      "\\n\\nPSE: " + preview.partnerRepName +\n      "\\nPSE field: " + (preview.partnerRepNeedsPopulate ? "Populate from Partner Owner" : "Keep existing value") +\n      "\\nTeam role: " + TEAM_ROLE + " (Opportunity Access: Read Only)" +\n      "\\nSplit: " + SPLIT_PERCENTAGE + "% " + SPLIT_TYPE +\n      "\\nSalesforce org: " + state.writeApi.org + "\\n\\nOnly blank PSE fields and missing Team/Split entries are added. Existing entries are preserved. Proceed?"\n    );\n    if (!okay) { message.textContent = "Cancelled — no Salesforce change was made."; button.disabled = false; return; }\n    message.textContent = "Updating Salesforce…";\n    const result = await postJson("/api/write", { oppId, confirm: "CONFIRM" });\n    setRowState(oppId, result);\n    if (!result.done) { renderUpdate(); throw new Error(result.error || "Salesforce did not confirm both the team and split updates."); }\n    renderUpdate();\n  } catch (error) {\n    if (error.message.toLowerCase().includes("salesforce login")) state.writeApi.loggedIn = false;\n    const current = document.querySelector(\'[data-msg="\' + CSS.escape(oppId) + \'"]\');\n    if (current) { current.textContent = error.message; current.className = "msg err"; }\n    button.disabled = false;\n  } finally {\n    const text = document.querySelector(\'[data-msg="\' + CSS.escape(oppId) + \'"]\')?.textContent;\n    const error = document.querySelector(\'[data-msg="\' + CSS.escape(oppId) + \'"]\')?.classList.contains(\'err\');\n    setBusy(false);\n    const current = document.querySelector(\'[data-msg="\' + CSS.escape(oppId) + \'"]\');\n    if (current && text) { current.textContent = text; current.className = error ? \'msg err\' : \'msg\'; }\n  }\n}\n\nasync function updateAll() {\n  if (state.busy) return;\n  const rows = filteredRows();\n  const ids = rows.map((row) => row.id).filter(Boolean);\n  if (!ids.length) return;\n  setBusy(true);\n  const button = $("updateAllBtn");\n  const message = $("bulkMsg");\n  button.disabled = true;\n  message.className = "msg";\n  message.textContent = "Checking current Salesforce status…";\n  try {\n    if (!(await ensureWriteLogin())) throw new Error("Salesforce login is required before updating.");\n    const preview = await postJson("/api/preview-all", { oppIds: ids });\n    if (!preview.idsToAdd.length) {\n      Object.entries(preview.states || {}).forEach(([id, status]) =>\n        setRowState(id, status));\n      renderUpdate();\n      message.textContent = "No eligible updates remain. The records are complete, changed scope, or have an unavailable Partner Owner. Refresh for current status.";\n      return;\n    }\n    Object.entries(preview.states || {}).forEach(([id, status]) =>\n      setRowState(id, status));\n    renderUpdate();\n    const okay = window.confirm(\n      "Update " + preview.idsToAdd.length.toLocaleString() + " Opportunities in " + state.writeApi.org +\n      "?\\n\\nKeep the existing PSE. If blank, populate it from the tagged Partner’s Owner. Then add the PSE to the Opportunity Team (" + TEAM_ROLE + ", Read Only) if missing, followed by a 100% Overlay Split (" + TEAM_ROLE + ") if the rep has no existing Split.\\n\\nExisting field values and Team/Split entries are preserved. This applies to all results across all pages using your current filters and rechecks Salesforce before each stage."\n    );\n    if (!okay) { message.textContent = "Cancelled — no Salesforce changes were made."; button.disabled = false; return; }\n    message.textContent = "Updating Salesforce… this may take several minutes.";\n    const result = await postJson("/api/write-all", { oppIds: preview.idsToAdd, confirm: "CONFIRM" });\n    Object.entries(result.states || {}).forEach(([id, status]) =>\n      setRowState(id, status));\n    message.className = result.failed ? "msg err" : "msg ok";\n    message.textContent = fmtCount(result.succeeded) + " fully updated · " + fmtCount(result.fieldPopulated) + " PSE fields populated · " + fmtCount(result.teamAdded) + " team adds · " +\n      fmtCount(result.splitAdded) + " split adds" + (result.failed ? " · " + fmtCount(result.failed) + " incomplete" : "") +\n      ((result.inactive || result.changed || result.excluded) ? " · " + fmtCount((result.inactive || 0) + (result.changed || 0) + (result.excluded || 0)) + " skipped" : "");\n    if ((result.errors || []).length) message.textContent += " · " + result.errors.map((item) => (item.oppId ? item.oppId + ": " : "") + item.message).join("; ");\n    render();\n  } catch (error) {\n    if (error.message.toLowerCase().includes("salesforce login")) state.writeApi.loggedIn = false;\n    message.className = "msg err";\n    message.textContent = "Update failed: " + error.message;\n  } finally {\n    setBusy(false);\n  }\n}\n\nasync function reloadSnapshot() {\n  const response = await fetch("pse-data.json?_=" + Date.now(), { cache: "no-store" });\n  if (!response.ok) throw new Error("Could not reload the dashboard snapshot.");\n  if (!hydrate(await response.json())) throw new Error("The saved data does not match the current dashboard scope. Click Refresh again.");\n}\n\nasync function refreshData() {\n  if (state.busy) return;\n  setBusy(true);\n  const button = $("refreshBtn");\n  const message = $("refreshMsg");\n  button.disabled = true; button.textContent = "Refreshing…";\n  message.className = "sub";\n  message.textContent = "Refreshing Salesforce… This can take a few minutes.";\n  try {\n    if (!(await ensureWriteLogin())) throw new Error("Salesforce login is required to refresh the dashboard.");\n    const result = await postJson("/api/refresh", { manual: true });\n    if (result.jobId) {\n      let complete = false;\n      while (!complete) {\n        await new Promise((resolve) => setTimeout(resolve, 1500));\n        const response = await fetch("/api/refresh-status?jobId=" + encodeURIComponent(result.jobId), { cache: "no-store" });\n        const job = await response.json();\n        if (!response.ok) throw new Error(job.error || ("HTTP " + response.status));\n        message.textContent = job.message || "Refreshing Salesforce data…";\n        if (job.status === "failed") throw new Error(job.message || "Salesforce refresh failed.");\n        complete = job.status === "complete";\n      }\n    }\n    await reloadSnapshot();\n    message.className = "sub ok";\n    message.textContent = "Refreshed · " + fmtCount((result.summary || state.summary).total) + " in-scope Partner Opportunities";\n  } catch (error) {\n    if (error.message.toLowerCase().includes("salesforce session expired")) state.writeApi.loggedIn = false;\n    message.className = "sub err"; message.textContent = "Refresh failed: " + error.message;\n  } finally { button.textContent = "Refresh"; setBusy(false); }\n}\n\nfunction csvCell(value) { return \'"\' + String(value == null ? "" : value).replace(/"/g, \'""\') + \'"\'; }\nfunction exportCsv() {\n  const rows = filteredRows();\n  const columns = ["id", "name", "stage", "closeDate", "fiscalQuarter", "type", "account", "accountOwner", "segment", "region", "partnerName", "partnerOwnerName", "partnerRepName", "partnerRepId", "partnerRepNeedsPopulate", "partnerRepActive", "partnerRepOnTeam", "partnerRepOnSplit"];\n  const lines = [columns.join(","), ...rows.map((row) => columns.map((key) => csvCell(row[key])).join(","))];\n  const blob = new Blob(["\\ufeff" + lines.join("\\r\\n")], { type: "text/csv;charset=utf-8" });\n  const url = URL.createObjectURL(blob); const anchor = document.createElement("a");\n  anchor.href = url; anchor.download = "pse_to_update.csv"; anchor.click(); URL.revokeObjectURL(url);\n}\n\nfunction wire() {\n  if (wired) return;\n  wired = true;\n  document.querySelectorAll("[data-pse-category]").forEach((button) => {\n    button.addEventListener("click", () => {\n      state.pseCategory = button.dataset.pseCategory;\n      state.updatePage = 1;\n      $("bulkMsg").textContent = "";\n      renderUpdate();\n    });\n  });\n  const process = $("processFlow");\n  let priorOverflow = "";\n  $("processFlowBtn").addEventListener("click", () => {\n    priorOverflow = document.body.style.overflow;\n    document.body.style.overflow = "hidden";\n    process.showModal();\n    process.scrollTop = 0;\n  });\n  $("closeProcessFlow").addEventListener("click", () => process.close());\n  process.addEventListener("close", () => {\n    document.body.style.overflow = $("uploadPage").open ? "hidden" : priorOverflow;\n    if (!$("uploadPage").open) $("processFlowBtn").focus({ preventScroll: true });\n  });\n  $("search").addEventListener("input", (event) => {\n    clearTimeout(searchTimer);\n    state.query = event.target.value.trim().toLowerCase();\n    state.updatePage = 1;\n    searchTimer = setTimeout(render, 160);\n  });\n  [["quarterFilter", "fiscalQuarter"], ["typeFilter", "type"], ["segmentFilter", "segment"], ["regionFilter", "region"], ["pseStatusFilter", "pseStatus"]].forEach(([id, key]) => {\n    const component = $(id);\n    const button = $(id + "Button");\n    button.addEventListener("click", () => {\n      document.querySelectorAll(".multi-filter").forEach((other) => {\n        if (other !== component) {\n          $(other.id + "Menu").classList.add("hidden");\n          $(other.id + "Button").setAttribute("aria-expanded", "false");\n        }\n      });\n      const menu = $(id + "Menu");\n      menu.classList.toggle("hidden");\n      button.setAttribute("aria-expanded", String(!menu.classList.contains("hidden")));\n    });\n    component.addEventListener("change", (event) => {\n      if (!event.target.matches("input[data-filter-option]")) return;\n      const selected = new Set(state[key]);\n      if (event.target.checked) selected.add(event.target.value);\n      else selected.delete(event.target.value);\n      state[key] = selected;\n      renderFilter(id, key, state.filterOptions[key]);\n      state.updatePage = 1;\n      render();\n    });\n    component.addEventListener("click", (event) => {\n      const action = event.target.closest("button[data-filter-select-all], button[data-filter-clear]");\n      if (!action) return;\n      event.stopPropagation();\n      state[key] = action.hasAttribute("data-filter-select-all")\n        ? new Set(state.filterOptions[key]) : new Set();\n      renderFilter(id, key, state.filterOptions[key]);\n      state.updatePage = 1;\n      render();\n    });\n  });\n  document.addEventListener("click", (event) => {\n    if (event.target.closest(".multi-filter")) return;\n    document.querySelectorAll(".multi-filter").forEach((component) => {\n      $(component.id + "Menu").classList.add("hidden");\n      $(component.id + "Button").setAttribute("aria-expanded", "false");\n    });\n  });\n  document.addEventListener("keydown", (event) => {\n    if (event.key !== "Escape") return;\n    document.querySelectorAll(".multi-filter").forEach((component) => {\n      $(component.id + "Menu").classList.add("hidden");\n      $(component.id + "Button").setAttribute("aria-expanded", "false");\n    });\n  });\n  $("actionPrev").addEventListener("click", () => { state.updatePage = Math.max(1, state.updatePage - 1); renderUpdate(); });\n  $("actionNext").addEventListener("click", () => { state.updatePage += 1; renderUpdate(); });\n  $("updateAllBtn").addEventListener("click", updateAll);\n  let uploadPriorOverflow = "";\n  const openUploadPage = () => {\n    if ($("uploadPage").open) return;\n    uploadPriorOverflow = document.body.style.overflow;\n    document.body.style.overflow = "hidden";\n    $("uploadPage").showModal();\n    $("uploadPage").scrollTop = 0;\n  };\n  $("uploadDataBtn").addEventListener("click", openUploadPage);\n  const openSetupInstructions = () => {\n    if (process.open) process.close();\n    openUploadPage();\n    $("setupInstructions").showModal();\n    $("setupInstructions").scrollTop = 0;\n    $("copySetupMsg").textContent = "";\n  };\n  $("firstTimeProcessLink").addEventListener("click", openSetupInstructions);\n  $("firstTimeUploadLink").addEventListener("click", openSetupInstructions);\n  $("closeSetupInstructions").addEventListener("click", () => $("setupInstructions").close());\n  $("setupInstructions").addEventListener("close", () => {\n    $("firstTimeUploadLink").focus({ preventScroll: true });\n  });\n  const copyCodexPrompt = async (promptId, messageId) => {\n    try {\n      await navigator.clipboard.writeText($(promptId).value);\n      $(messageId).textContent = "Copied. Paste the prompt into your Codex chat and send it.";\n    } catch (_) {\n      $(promptId).focus();\n      $(promptId).select();\n      $(messageId).textContent = "Select and copy the highlighted prompt, then paste it into your Codex chat.";\n    }\n  };\n  $("copySetupPrompt").addEventListener("click", () => copyCodexPrompt("setupPrompt", "copySetupMsg"));\n  $("copyDownloadPrompt").addEventListener("click", () => copyCodexPrompt("downloadPrompt", "copyDownloadMsg"));\n  $("closeUploadPage").addEventListener("click", () => $("uploadPage").close());\n  $("uploadPage").addEventListener("close", () => {\n    document.body.style.overflow = uploadPriorOverflow;\n    $("uploadDataBtn").focus({ preventScroll: true });\n  });\n  $("uploadFile").addEventListener("change", event => previewUpload(event.target.files[0]));\n  $("confirmUploadBtn").addEventListener("click", () => uploadData());\n  $("refreshBtn").addEventListener("click", () => refreshData());\n  $("csvBtn").addEventListener("click", exportCsv);\n}\n\nload();\n'

