exec('"""Shared Partner → PSE → Team → Splits rules for local and hosted dashboards."""\nfrom __future__ import annotations\n\nimport datetime as dt\nfrom email.utils import format_datetime\n\nPARTNER_FIELD = \'Referring_Partner__c\'\nPARTNER_REL = \'Referring_Partner__r\'\nTEAM_ROLE = \'Partner Account Executive\'\nOPPORTUNITY_TYPES = (\'Renewal\', \'New Business\', \'Expansion\')\nSCOPE_VERSION = 4\nCLOSED_STAGE = \'08 - Closed\'\nAPI_VERSION = \'v60.0\'\nREP_FIELDS = (f\'{PARTNER_FIELD}, {PARTNER_REL}.Name, {PARTNER_REL}.OwnerId, \'\n              f\'{PARTNER_REL}.Owner.Name, {PARTNER_REL}.Owner.IsActive, \'\n              \'Partner_Sales_Rep__c, Partner_Sales_Rep__r.Name, Partner_Sales_Rep__r.IsActive, LastModifiedDate\')\n\n\ndef in_scope(record):\n    return (bool(record.get(PARTNER_FIELD)) and record.get(\'Non_Commissionable__c\') is False\n            and record.get(\'Type\') in OPPORTUNITY_TYPES and record.get(\'StageName\') == CLOSED_STAGE)\n\n\ndef rep_state(record, team=(), splits=()):\n    partner = record.get(PARTNER_REL) or {}\n    populate = not bool(record.get(\'Partner_Sales_Rep__c\'))\n    rep_id = partner.get(\'OwnerId\') if populate else record.get(\'Partner_Sales_Rep__c\')\n    rep = (partner.get(\'Owner\') or {}) if populate else (record.get(\'Partner_Sales_Rep__r\') or {})\n    valid_user = bool(rep_id and rep_id.startswith(\'005\'))\n    on_team, on_split = bool(rep_id and rep_id in team), bool(rep_id and rep_id in splits)\n    complete = not populate and on_team and on_split\n    missing = []\n    if populate: missing.append(\'Partner Sales Rep field\')\n    if not on_team: missing.append(\'Opportunity Team\')\n    if not on_split: missing.append(\'Opportunity Splits\')\n    return {\'stage\': record.get(\'StageName\'), \'partnerId\': record.get(PARTNER_FIELD), \'partnerName\': partner.get(\'Name\'),\n            \'partnerOwnerName\': (partner.get(\'Owner\') or {}).get(\'Name\'),\n            \'partnerRepId\': rep_id, \'partnerRepName\': rep.get(\'Name\') or \'(user unavailable)\',\n            \'partnerRepActive\': rep.get(\'IsActive\'), \'partnerRepNeedsPopulate\': populate,\n            \'partnerRepSource\': \'partner_owner\' if populate else \'existing\',\n            \'partnerRepOnTeam\': on_team, \'partnerRepOnSplit\': on_split,\n            \'blockedReason\': \'\' if valid_user else \'The Partner Owner could not be resolved to a Salesforce user.\',\n            \'bucket\': \'complete\' if complete else \'needs_call\',\n            \'reason\': \'PSE field, Team and Splits are complete\' if complete else \'Missing: \' + \', \'.join(missing)}\n\n\ndef is_complete(row):\n    return not row.get(\'partnerRepNeedsPopulate\') and row.get(\'partnerRepOnTeam\') and row.get(\'partnerRepOnSplit\')\n\n\ndef summary(rows):\n    complete = sum(bool(is_complete(row)) for row in rows)\n    return {\'total\': len(rows), \'tagged\': complete, \'needsUpdate\': len(rows) - complete,\n            \'needsPopulate\': sum(bool(row.get(\'partnerRepNeedsPopulate\')) for row in rows)}\n\n\ndef read_states(ids, query):\n    quoted = \',\'.join("\'" + value + "\'" for value in ids)\n    records = query(\'SELECT Id, Name, StageName, Type, Non_Commissionable__c, \' + REP_FIELDS +\n                    f\' FROM Opportunity WHERE Id IN ({quoted})\')\n    team, splits = {}, {}\n    for row in query(f\'SELECT OpportunityId, UserId FROM OpportunityTeamMember WHERE OpportunityId IN ({quoted})\'):\n        team.setdefault(row[\'OpportunityId\'], set()).add(row[\'UserId\'])\n    for row in query(f\'SELECT OpportunityId, SplitOwnerId FROM OpportunitySplit WHERE OpportunityId IN ({quoted})\'):\n        splits.setdefault(row[\'OpportunityId\'], set()).add(row[\'SplitOwnerId\'])\n    by_id = {row[\'Id\']: row for row in records}\n    states = {key: rep_state(row, team.get(key, ()), splits.get(key, ()))\n              for key, row in by_id.items() if in_scope(row)}\n    return by_id, states\n\n\ndef execute(ids, allowed, query, rest, split_type, write=False):\n    """Preview or apply ordered rules; isolate failures and verify actual Salesforce state."""\n    unique_ids = list(dict.fromkeys(ids))\n    requested = [value for value in unique_ids if value in allowed]\n    states, errors, ids_to_add = {}, [], []\n    counts = {\'fieldPopulated\': 0, \'teamAdded\': 0, \'splitAdded\': 0, \'alreadyComplete\': 0,\n              \'excluded\': len(unique_ids) - len(requested), \'inactive\': 0}\n    failed, succeeded, changed = set(), set(), set()\n    resolved_split_type = None\n\n    def recheck(batch):\n        records, current = read_states(batch, query)\n        for key in batch:\n            if key not in current:\n                changed.add(key)\n                states[key] = {\'inScope\': False, \'reason\': \'Opportunity no longer meets the closed Partner scope or is no longer accessible.\'}\n        for key, value in current.items():\n            value[\'inScope\'] = True\n            changed.discard(key)\n        return records, current\n\n    def record_error(key, object_name, detail):\n        failed.add(key)\n        errors.append({\'oppId\': key, \'object\': object_name, \'message\': str(detail)[:500]})\n\n    def insert_many(object_name, records, counter):\n        if not records:\n            return\n        try:\n            status, result = rest(\'POST\', f\'/services/data/{API_VERSION}/composite/sobjects\',\n                {\'allOrNone\': False, \'records\': [{\'attributes\': {\'type\': object_name}, **row} for _, row in records]})\n            if status not in (200, 201) or not isinstance(result, list) or len(result) != len(records):\n                raise RuntimeError(f\'Salesforce {object_name} response could not be confirmed: {str(result)[:350]}\')\n        except (RuntimeError, OSError, ValueError) as error:\n            for key, _ in records:\n                record_error(key, object_name, error)\n            return\n        for (key, _), response in zip(records, result):\n            if isinstance(response, dict) and response.get(\'success\'):\n                counts[counter] += 1\n            else:\n                record_error(key, object_name, response.get(\'errors\', response) if isinstance(response, dict) else response)\n\n    def reconcile(batch, current):\n        states.update(current)\n        for key in batch:\n            if key in changed:\n                failed.discard(key)\n                succeeded.discard(key)\n            elif key in current and is_complete(current[key]):\n                succeeded.add(key)\n                failed.discard(key)\n            else:\n                failed.add(key)\n\n    for start in range(0, len(requested), 200):\n        batch = requested[start:start + 200]\n        try:\n            records, current = recheck(batch)\n            for key, value in current.items():\n                if is_complete(value):\n                    counts[\'alreadyComplete\'] += 1\n                elif value[\'blockedReason\']:\n                    record_error(key, \'User\', value[\'blockedReason\'])\n                else:\n                    ids_to_add.append(key)\n            if not write:\n                states.update(current)\n                continue\n            # Populate only blank fields. A concurrent Opportunity edit rejects this write.\n            for key, value in current.items():\n                if key in failed or not value[\'partnerRepNeedsPopulate\']:\n                    continue\n                try:\n                    modified = records[key].get(\'LastModifiedDate\')\n                    if not modified:\n                        raise ValueError(\'Missing record version; refresh before populating the PSE.\')\n                    timestamp = dt.datetime.strptime(modified, \'%Y-%m-%dT%H:%M:%S.%f%z\').astimezone(dt.timezone.utc)\n                    status, response = rest(\'PATCH\', f\'/services/data/{API_VERSION}/sobjects/Opportunity/{key}\',\n                        {\'Partner_Sales_Rep__c\': value[\'partnerRepId\']},\n                        headers={\'If-Unmodified-Since\': format_datetime(timestamp, usegmt=True)})\n                    if status not in (200, 204):\n                        raise RuntimeError(str(response))\n                    counts[\'fieldPopulated\'] += 1\n                except (RuntimeError, OSError, ValueError) as error:\n                    record_error(key, \'Opportunity\', error)\n            # Re-read after every stage to observe assignment changes and Salesforce automation.\n            _, current = recheck(batch)\n            members = [(key, {\'OpportunityId\': key, \'UserId\': value[\'partnerRepId\'],\n                        \'TeamMemberRole\': TEAM_ROLE, \'OpportunityAccessLevel\': \'Read\'})\n                       for key, value in current.items() if key not in failed and not value[\'blockedReason\']\n                       and not value[\'partnerRepNeedsPopulate\'] and not value[\'partnerRepOnTeam\']]\n            insert_many(\'OpportunityTeamMember\', members, \'teamAdded\')\n            _, current = recheck(batch)\n            pending_splits = [(key, value) for key, value in current.items()\n                              if key not in failed and not value[\'blockedReason\']\n                              and not value[\'partnerRepNeedsPopulate\'] and value[\'partnerRepOnTeam\']\n                              and not value[\'partnerRepOnSplit\']]\n            if pending_splits:\n                if resolved_split_type is None:\n                    resolved_split_type = split_type()\n                splits = [(key, {\'OpportunityId\': key, \'SplitOwnerId\': value[\'partnerRepId\'],\n                           \'SplitTypeId\': resolved_split_type, \'Opportunity_Team_Role__c\': TEAM_ROLE, \'SplitPercentage\': 100})\n                          for key, value in pending_splits]\n                insert_many(\'OpportunitySplit\', splits, \'splitAdded\')\n            _, current = recheck(batch)\n            reconcile(batch, current)\n        except (RuntimeError, OSError, ValueError) as error:\n            if not write:\n                raise\n            errors.append({\'message\': str(error)[:500]})\n            failed.update(batch)\n            # A timeout can occur after Salesforce accepts a write. Reconcile before reporting failure.\n            try:\n                _, latest = recheck(batch)\n                reconcile(batch, latest)\n            except (RuntimeError, OSError, ValueError):\n                pass\n    return {**counts, \'changed\': len(changed), \'states\': states, \'idsToAdd\': ids_to_add,\n            \'succeeded\': len(succeeded), \'succeededIds\': sorted(succeeded),\n            \'failed\': len(failed), \'errors\': errors[:50]}\n', _module.__dict__)
sys.modules['workflow'] = _module
_module = types.ModuleType('snapshot')
exec('"""Validate portable dashboard exports before replacing the saved snapshot."""\nimport datetime as dt\nimport math\nimport re\n\nfrom workflow import CLOSED_STAGE, OPPORTUNITY_TYPES, PARTNER_FIELD, SCOPE_VERSION, summary\n\nMAX_UPLOAD_BYTES = 25 * 1024 * 1024\nTEXT_FIELDS = (\'name\', \'account\', \'accountOwner\', \'stage\', \'closeDate\', \'type\', \'segment\', \'region\',\n               \'partnerName\', \'partnerOwnerName\', \'partnerRepName\', \'partnerRepSource\', \'blockedReason\', \'bucket\', \'reason\')\nBOOL_FIELDS = (\'partnerRepNeedsPopulate\', \'partnerRepOnTeam\', \'partnerRepOnSplit\')\n\n\ndef validate_snapshot(value):\n    if not isinstance(value, dict) or not isinstance(value.get(\'config\'), dict):\n        raise ValueError(\'Choose the pse-data.json file generated by the local Salesforce export command.\')\n    if value[\'config\'].get(\'scopeVersion\') != SCOPE_VERSION:\n        raise ValueError(\'This file uses an older dashboard scope. Export fresh data using the current command.\')\n    generated = value.get(\'generatedAt\')\n    try:\n        timestamp = dt.datetime.fromisoformat(generated.replace(\'Z\', \'+00:00\'))\n        if timestamp.tzinfo is None: raise ValueError()\n    except (AttributeError, TypeError, ValueError):\n        raise ValueError(\'The export must have a valid Salesforce extraction date with timezone.\') from None\n    if not isinstance(value.get(\'rows\'), list):\n        raise ValueError(\'The export must contain an Opportunity rows list.\')\n    rows, seen = [], set()\n    for number, row in enumerate(value[\'rows\'], 1):\n        if not isinstance(row, dict): raise ValueError(f\'Row {number} is not an Opportunity record.\')\n        opp_id = row.get(\'id\')\n        if not isinstance(opp_id, str) or not re.fullmatch(r\'006[A-Za-z0-9]{12}(?:[A-Za-z0-9]{3})?\', opp_id):\n            raise ValueError(f\'Row {number} has an invalid Opportunity ID.\')\n        if opp_id in seen: raise ValueError(f\'Duplicate Opportunity ID at row {number}.\')\n        seen.add(opp_id)\n        if (row.get(\'stage\') != CLOSED_STAGE or row.get(\'type\') not in OPPORTUNITY_TYPES\n                or row.get(\'nonCommissionable\') is not False or not row.get(\'partnerId\')):\n            raise ValueError(f\'Row {number} is outside the closed, commissionable Opportunity scope with a Partner.\')\n        for field in BOOL_FIELDS:\n            if type(row.get(field)) is not bool: raise ValueError(f\'Row {number} is missing a valid {field} check.\')\n        if row.get(\'partnerRepActive\') is not None and type(row[\'partnerRepActive\']) is not bool:\n            raise ValueError(f\'Row {number} has an invalid PSE status.\')\n        clean = {\'id\': opp_id, \'nonCommissionable\': False, **{field: row[field] for field in BOOL_FIELDS}}\n        for field in TEXT_FIELDS:\n            item = row.get(field)\n            if item is not None and (not isinstance(item, str) or len(item) > 10000):\n                raise ValueError(f\'Row {number} has an invalid {field} value.\')\n            clean[field] = item\n        try: dt.date.fromisoformat(row.get(\'closeDate\'))\n        except (TypeError, ValueError): raise ValueError(f\'Row {number} has an invalid Close Date.\') from None\n        for field, prefix in ((\'partnerId\', \'001\'), (\'partnerRepId\', \'005\')):\n            item = row.get(field)\n            if item is not None and (not isinstance(item, str) or not re.fullmatch(prefix + r\'[A-Za-z0-9]{12}(?:[A-Za-z0-9]{3})?\', item)):\n                raise ValueError(f\'Row {number} has an invalid {field}.\')\n            clean[field] = item\n        amount = row.get(\'amount\')\n        try:\n            valid_amount = amount is None or (type(amount) in (int, float) and math.isfinite(amount))\n        except OverflowError:\n            valid_amount = False\n        if not valid_amount:\n            raise ValueError(f\'Row {number} has an invalid amount.\')\n        clean.update(amount=amount, partnerRepActive=row.get(\'partnerRepActive\'))\n        rows.append(clean)\n    return {\'generatedAt\': generated,\n            \'config\': {\'scopeVersion\': SCOPE_VERSION, \'stage\': CLOSED_STAGE, \'partnerField\': PARTNER_FIELD,\n                       \'scope\': \'Commissionable 08 - Closed Renewal, New Business, and Expansion opportunities\',\n                       \'commissionableOnly\': True, \'splitCheck\': \'any\', \'opportunityTypes\': list(OPPORTUNITY_TYPES)},\n            \'rows\': rows, \'summary\': summary(rows)}\n', _module.__dict__)
sys.modules['snapshot'] = _module
from snapshot import MAX_UPLOAD_BYTES, validate_snapshot
from workflow import CLOSED_STAGE, PARTNER_FIELD, SCOPE_VERSION

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = MAX_UPLOAD_BYTES + 1024
_ENGINE = None
_ENGINE_LOCK = threading.Lock()


def _database_url():
    for key in ('DATABASE_URL', 'POSTGRES_URL', 'POSTGRESQL_URL', 'PG_URL', 'DB_URL'):
        value = os.environ.get(key)
        if value:
            return value.replace('postgres://', 'postgresql://', 1) if value.startswith('postgres://') else value
    host = os.environ.get('DB_HOST') or os.environ.get('PGHOST') or os.environ.get('POSTGRES_HOST')
    user = os.environ.get('DB_USER') or os.environ.get('PGUSER') or os.environ.get('POSTGRES_USER')
    password = os.environ.get('DB_PASSWORD') or os.environ.get('PGPASSWORD') or os.environ.get('POSTGRES_PASSWORD', '')
    name = os.environ.get('DB_NAME') or os.environ.get('PGDATABASE') or os.environ.get('POSTGRES_DB')
    port = os.environ.get('DB_PORT') or os.environ.get('PGPORT', '5432')
    if host and user and name:
        return URL.create('postgresql', username=user, password=password or None, host=host,
                          port=int(port), database=name).render_as_string(hide_password=False)
    raise RuntimeError('AppFoundry Postgres is required. Attach a PostgreSQL database to this app.')


def db():
    global _ENGINE
    if _ENGINE is None:
        with _ENGINE_LOCK:
            if _ENGINE is None:
                engine = create_engine(_database_url(), pool_pre_ping=True, pool_size=5, max_overflow=10)
                try:
                    with engine.begin() as cx:
                        cx.execute(text('''CREATE TABLE IF NOT EXISTS pse_split_snapshot (
                            id SMALLINT PRIMARY KEY CHECK (id = 1), payload TEXT NOT NULL,
                            refreshed_at TIMESTAMPTZ NOT NULL DEFAULT NOW())'''))
                except Exception:
                    engine.dispose()
                    raise
                _ENGINE = engine
    return _ENGINE


def _load_snapshot():
    with db().begin() as cx:
        row = cx.execute(text('SELECT payload FROM pse_split_snapshot WHERE id=1')).first()
    return json.loads(row[0]) if row else {'generatedAt': None,
        'config': {'scopeVersion': SCOPE_VERSION, 'stage': CLOSED_STAGE, 'partnerField': PARTNER_FIELD},
        'summary': {'total': 0, 'tagged': 0, 'needsUpdate': 0}, 'rows': []}


@contextmanager
def snapshot_operation():
    with db().begin() as cx:
        cx.execute(text('SELECT pg_advisory_xact_lock(8773004)'))
        yield cx


def _save_snapshot(payload):
    with snapshot_operation() as cx:
        cx.execute(text('''INSERT INTO pse_split_snapshot (id, payload, refreshed_at) VALUES (1, :payload, NOW())
            ON CONFLICT (id) DO UPDATE SET payload=EXCLUDED.payload, refreshed_at=NOW()'''),
            {'payload': json.dumps(payload, ensure_ascii=False, allow_nan=False)})


@app.after_request
def no_cache(response):
    response.headers['Cache-Control'] = 'no-store'
    return response


@app.get('/')
def index():
    return Response(INDEX_HTML, mimetype='text/html')


@app.get('/app.js')
def javascript():
    return Response(APP_JS, mimetype='application/javascript')


@app.get('/api/health')
def health():
    return jsonify({'uploadEnabled': True, 'refreshEnabled': False, 'writeEnabled': False,
                    'authMode': 'upload', 'loggedIn': False, 'scopeVersion': SCOPE_VERSION})


@app.get('/pse-data.json')
def data_json():
    return jsonify(_load_snapshot())


@app.post('/api/upload')
def upload():
    body = request.get_json(silent=True)
    if not isinstance(body, dict) or body.get('manual') is not True:
        return jsonify({'error': 'Choose a data file and click Upload data to dashboard.'}), 400
    try:
        payload = validate_snapshot(body.get('snapshot'))
    except ValueError as error:
        return jsonify({'error': str(error)}), 400
    payload['uploadedAt'] = dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')
    _save_snapshot(payload)
    return jsonify({'ok': True, 'snapshot': payload})


@app.route('/api/refresh', methods=['POST'])
@app.route('/api/write', methods=['POST'])
@app.route('/api/write-all', methods=['POST'])
@app.route('/api/preview', methods=['POST'])
@app.route('/api/preview-all', methods=['POST'])
@app.route('/oauth/login')
@app.route('/oauth/callback')
def local_only():
    return jsonify({'error': 'This hosted dashboard uses uploaded data. Use the local app for Salesforce refreshes and updates.'}), 410


@app.errorhandler(Exception)
def app_error(error):
    if isinstance(error, HTTPException):
        message = 'Data file is too large. Maximum size is 25 MB.' if error.code == 413 else error.description
        return jsonify({'error': message}), error.code
    app.logger.exception('Dashboard request failed')
    return jsonify({'error': 'The saved data could not be accessed. Check the AppFoundry database configuration and runtime logs.'}), 503


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', '8080')))
